import sys
import os
import json

sys.path.append('storage/shared')
sys.path.append('storage/logos')

from cognitive_plasticity.analysis import run_full_analysis

def load_cps_v0_data(agent_name="Zephyr IV"):
    """Loads and parses the specified agent's beacon data for the CPS_v0 study."""
    beacons = []
    beacon_file = f"storage/shared/meta/sas/beacons/{agent_name}_beacons.jsonl"
    print(f"Attempting to load data from: {beacon_file}")
    try:
        with open(beacon_file, 'r') as f:
            for line in f:
                try:
                    beacon = json.loads(line)
                    if beacon.get("notes", "").startswith("CPS_v0:"):
                        beacons.append(beacon)
                except json.JSONDecodeError:
                    continue # Skip empty or malformed lines
        print(f"Successfully loaded and filtered {len(beacons)} CPS_v0 beacons for {agent_name}.")
        return beacons
    except FileNotFoundError:
        print(f"Error: Beacon file not found for {agent_name}.")
        return []

if __name__ == '__main__':
    # Load the experimental data
    experimental_data = load_cps_v0_data()

    # Run the analysis script I prepared
    if experimental_data:
        run_full_analysis(experimental_data)
    else:
        print("Analysis aborted due to lack of data.")
